    &&equal((await searchAuditAnchors(db,[],gymOwnIdentityIds)).identities,proof.firstGymRetainedOwnIdentitiesBefore)
     &&equal((await searchAuditAnchors(db,[],firstOtherOwnIdentityIds)).identities,proof.firstOtherRetainedOwnIdentitiesBefore)
    &&equal(await searchAuditAnchors(db,null,auditedIdentityIds),proof.allAuditAndAuditedIdentitiesBefore)
    &&equal(await graphHash(db,retainedCustomers),proof.retainedScopeBefore)
    &&equal((await searchAuditAnchors(db,[],retainedOwnIdentityIds)).identities,proof.retainedOwnIdentitiesBefore)
    &&equal(await ownedSessionHash(db),proof.ownedSessionsAfter),'POSTCOMMIT_PRESERVATION');
   proof.historicalSubsetsPreservedPostcommitByCompleteHash=true;await noOtherTransactions(db);await stoppedPort();
  };
 });
 transactionResolved=true;proof.transactionCommitted=true;phase='postcommit-preservation';
 await proof.postcommitCheck();delete proof.postcommitCheck;
 proof.postcommitPreservation=true;phase='known-db-close';await db.end({timeout:5});db=null;proof.databaseClosed=true;verified=true;
}catch(error){
 proof.phase=phase;proof.commitOutcomeUnknown=transactionStarted&&!transactionResolved;
 proof.failure={code:/^RECOVERY_[A-Z0-9_]+$/.test(error?.message??'')?error.message:/^[A-Z0-9]{5}$/.test(error?.code??'')?error.code:'CONTROLLED_RECOVERY_FAILURE'};
